CREATE TABLE rm_intercompany_disposition_lifecycle_events (
  id INTEGER PRIMARY KEY,
  disposition_id TEXT NOT NULL REFERENCES rm_intercompany_dispositions(disposition_id),
  event_type TEXT NOT NULL CHECK(event_type IN ('settled','superseded','reopened','exception','exception_resolved')),
  payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),
  canonical_payload TEXT NOT NULL,
  actor TEXT NOT NULL,
  principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service')),
  principal_id TEXT NOT NULL,
  previous_hash TEXT,
  event_hash TEXT NOT NULL UNIQUE CHECK(length(event_hash)=64),
  created_at TEXT NOT NULL
);
CREATE INDEX rm_intercompany_disposition_lifecycle_lookup ON rm_intercompany_disposition_lifecycle_events(disposition_id,id);
CREATE TRIGGER rm_intercompany_disposition_lifecycle_events_no_update BEFORE UPDATE ON rm_intercompany_disposition_lifecycle_events BEGIN SELECT RAISE(ABORT, 'intercompany disposition lifecycle is append-only'); END;
CREATE TRIGGER rm_intercompany_disposition_lifecycle_events_no_delete BEFORE DELETE ON rm_intercompany_disposition_lifecycle_events BEGIN SELECT RAISE(ABORT, 'intercompany disposition lifecycle is append-only'); END;
